package com.example.Libraray_Management_RESTAPI.model;

import jakarta.validation.constraints.Max;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

/**
 * (a) Book model class.
 * Each book record has: id, title, author, category and availableCopies.
 */
public class Book {

    // Generated by the server when a book is added
    private Integer id;

    @NotBlank(message = "Title is required")
    @Size(max = 100, message = "Title must be at most 100 characters")
    private String title;

    @NotBlank(message = "Author is required")
    @Size(max = 60, message = "Author must be at most 60 characters")
    private String author;

    @NotBlank(message = "Category is required")
    @Size(max = 40, message = "Category must be at most 40 characters")
    private String category;

    @NotNull(message = "Available copies is required")
    @Min(value = 0, message = "Available copies cannot be negative")
    @Max(value = 10000, message = "Available copies must be at most 10000")
    private Integer availableCopies;

    // Default constructor (needed by Spring to convert JSON into a Book object)
    public Book() {
    }

    // Constructor with all fields
    public Book(Integer id, String title, String author, String category, Integer availableCopies) {
        this.id = id;
        this.title = title;
        this.author = author;
        this.category = category;
        this.availableCopies = availableCopies;
    }

    // Getters and setters

    public Integer getId() {
        return id;
    }

    public void setId(Integer id) {
        this.id = id;
    }

    public String getTitle() {
        return title;
    }

    public void setTitle(String title) {
        this.title = title;
    }

    public String getAuthor() {
        return author;
    }

    public void setAuthor(String author) {
        this.author = author;
    }

    public String getCategory() {
        return category;
    }

    public void setCategory(String category) {
        this.category = category;
    }

    public Integer getAvailableCopies() {
        return availableCopies;
    }

    public void setAvailableCopies(Integer availableCopies) {
        this.availableCopies = availableCopies;
    }

    @Override
    public String toString() {
        return "Book [id=" + id + ", title=" + title + ", author=" + author + ", category=" + category
                + ", availableCopies=" + availableCopies + "]";
    }
}
